+  String.raw`(^|\s)!?(?:\S*:)?!?` +
+    String.raw`(?:bg|text|border(?:-[xytrblse])?|ring(?:-offset)?|divide|from|via|to|outline|stroke|fill|shadow|caret|accent|decoration|placeholder)` +
